// TestReaderWatchStub checks the methods of ReaderWatchStub, which
// configures Watch.
func TestReaderWatchStub(t *testing.T) {
	t.Parallel()

	t.Run("Yields", func(t *testing.T) {
		t.Parallel()

		t.Run("yields each item", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewReaderStub(t)
			var want store.Event
			s.OnWatch.Yields(want, want)
			got0 := readerStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
			}
			assert.Equal(t, seen, 2, "Watch yields each item")
		})

		t.Run("stops yielding when the caller breaks", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewReaderStub(t)
			var want store.Event
			s.OnWatch.Yields(want, want, want)
			got0 := readerStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
				break
			}
			assert.Equal(t, seen, 1, "Watch stops when the caller breaks")
		})
	})

	t.Run("YieldsError", func(t *testing.T) {
		t.Parallel()

		t.Run("yields the error after the items", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewReaderStub(t)
			var item store.Event
			want := errors.New("Watch-yields")
			s.OnWatch.YieldsError([]store.Event{item, item}, want)
			got0 := readerStubWatch(t, s)
			seen := 0
			var last error
			for _, err := range got0 {
				if err != nil {
					last = err
					break
				}
				seen++
			}
			assert.Equal(t, seen, 2, "Watch yields each item before the error")
			assert.ErrorIs(t, last, want, "Watch ends with the error of YieldsError")
		})

		t.Run("stops the sequence when the caller breaks", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewReaderStub(t)
			var item store.Event
			s.OnWatch.YieldsError([]store.Event{item, item, item}, errors.New("Watch-yields"))
			got0 := readerStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
				break
			}
			assert.Equal(t, seen, 1, "Watch stops when the caller breaks")
		})
	})
}

