// TestWriterStub checks the methods, the constructors and the options of
// the double WriterStub.
func TestWriterStub(t *testing.T) {
	t.Parallel()

	t.Run("Commit", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Commit", writerStubCommitSubject)
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()

		t.Run("Commit", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Commit", writerStubCommitSubject)
		})
	})

	t.Run("WriterStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubStrict()))
		})
	})

	t.Run("WriterStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes Commit to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := storetest.NewWriterStub(t)
			s := storetest.NewWriterStub(t, storetest.WriterStubDelegateTo(inner))
			_, _ = writerStubCommit(t, s)
			inner.OnCommit.AssertCalledOnce(t, "Commit calls the implementation")
		})

		t.Run("fails Commit with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Commit-delegate")
			inner := storetest.NewWriterStub(t)
			inner.OnCommit.Faults(want, 1)
			s := storetest.NewWriterStub(t, storetest.WriterStubDelegateTo(inner))
			_, r1 := writerStubCommit(t, s)
			assert.ErrorIs(t, r1, want, "Commit fails with the error of the implementation")
		})
	})

	t.Run("WriterStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubWithClock(clk)))
		})
	})

	t.Run("WriterStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubWithRandSource(src)))
		})
	})

	t.Run("WriterStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubBenchMode()))
		})
	})

	t.Run("WriterStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) writerStubInstance {
			return writerStubInstanceOf(
				tb,
				storetest.NewWriterStub(tb, storetest.WriterStubWithClock(clk), storetest.WriterStubWithLatency(d)),
			)
		})
	})

	t.Run("WriterStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Commit with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Commit-failing")
			s := storetest.NewWriterStub(t, storetest.WriterStubFailing(want))
			_, r1 := writerStubCommit(t, s)
			assert.ErrorIs(t, r1, want, "Commit fails with the error of WriterStubFailing")
		})
	})

	t.Run("WithWriterCommit", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Commit", func(t *testing.T) {
			t.Parallel()
			called := false
			s := storetest.NewWriterStub(
				t,
				storetest.WithWriterCommit(
					func(_ context.Context, _ epoch.Epoch, _ *store.Mutation) (epoch.Epoch, error) {
						called = true
						var z0 epoch.Epoch
						var z1 error
						return z0, z1
					},
				),
			)
			_, _ = writerStubCommit(t, s)
			assert.True(t, called, "WithWriterCommit sets the function of Commit")
		})
	})
}

